import{_ as t,c as a,o,ae as i}from"./chunks/framework.Bi6zybwU.js";const c=JSON.parse('{"title":"Date Field","description":"Date Field","frontmatter":{"title":"Date Field","description":"Date Field"},"headers":[],"relativePath":"guide/field-types/date-field.md","filePath":"guide/field-types/date-field.md"}'),l={name:"guide/field-types/date-field.md"};function d(n,e,s,r,m,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="date-field" tabindex="-1">Date Field <a class="header-anchor" href="#date-field" aria-label="Permalink to &quot;Date Field&quot;">​</a></h1><p>The Date Field in a table column is to show dates with customized date formats. In Ninja Tables, the column with the Date Field will display a calendar. You can decide the data type as Date Field right from the start when you add a column to the table. From your dashboard, go to the Ninja Tables plugin → Tables (the table where you want to add Column) → Add Column.</p><h2 id="date-field-in-ninja-tables-column" tabindex="-1">Date Field In Ninja Tables Column <a class="header-anchor" href="#date-field-in-ninja-tables-column" aria-label="Permalink to &quot;Date Field In Ninja Tables Column&quot;">​</a></h2><p>This data type is used to add a date in the input field. You can customize the date format and change the format anytime. Ninja Tables gives you multiple customization options here as well. <img src="https://ninjatables.com/wp-content/uploads/2023/09/Date-field-in-column-1024x770.png" alt="Date field in column"></p><ul><li>Now a new column with Date Field as the data type has been added to the table. To see how it works, view the table backend. <img src="https://ninjatables.com/wp-content/uploads/2023/09/custom-date-field-1024x450.png" alt="custom date field"></li></ul><h3 id="date-format-standard" tabindex="-1">Date Format (Standard) <a class="header-anchor" href="#date-format-standard" aria-label="Permalink to &quot;Date Format (Standard)&quot;">​</a></h3><p>It indicates the pattern of the date value. The date field mainly includes 8 formats. <img src="https://ninjatables.com/wp-content/uploads/2023/09/standard-date-field-1024x564.png" alt="standard date field"></p><ul><li>The <strong>Date Format</strong> you select in your <strong>Column</strong> <strong>settings</strong> will automatically determine how the column values appear.</li><li>For example, see the below screenshot. We&#39;ve selected the date format to be MMM/DD/YYYY. <img src="https://ninjatables.com/wp-content/uploads/2023/09/date-format-1024x564.png" alt="date format"></li><li>When you select the date from the table backend, the date will appear exactly in this format- MMM/DD/YYYY. <img src="https://ninjatables.com/wp-content/uploads/2023/09/custom-date-format-1024x462.png" alt="custom date format"></li></ul><h3 id="date-format-custom" tabindex="-1">Date Format (Custom) <a class="header-anchor" href="#date-format-custom" aria-label="Permalink to &quot;Date Format (Custom)&quot;">​</a></h3><p>There is also a Date format option where a custom date can also be added if the default options do not meet your needs. You can put your custom date as per your requirements. Custom dates need to be in **moment.js **supported format. Custom Date Format is a Pro feature!</p><h2 id="show-time" tabindex="-1">Show Time <a class="header-anchor" href="#show-time" aria-label="Permalink to &quot;Show Time&quot;">​</a></h2><p>If you enable this option, then the <strong>time</strong> <strong>picker</strong> will be available. It includes mainly 12-time formats. <img src="https://ninjatables.com/wp-content/uploads/2023/09/Time-format-1024x679.png" alt="Time format"></p><h2 id="first-day" tabindex="-1">First Day <a class="header-anchor" href="#first-day" aria-label="Permalink to &quot;First Day&quot;">​</a></h2><p>It shows the first day of the week. For instance, Sunday, Monday, etc. Note that the Date Field data type is <strong>HTML</strong> supported. Add Date Field to your table columns easily with Ninja Tables! Let us know your thoughts.</p>',14)])])}const p=t(l,[["render",d]]);export{c as __pageData,p as default};
